css:
/* Global typography.
   Families come from site/tokens.json (fonts.heading = INTL Headline, fonts.body = INTL Text);
   the @font-face rules are generated from tokens.fonts.files. Only the family is set here — sizes,
   weights, colours and spacing stay with each component. */

/* H1-H6 (reset.css only covers h1-h4) */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); }

/* Native controls do not inherit a family on their own. */
button, input, select, textarea, optgroup { font-family: var(--font-body); }

/* Platform classes whose own rule asks for the heading family but which are not H1-H6
   (buttons, labels, eyebrows, nav links, card titles, chips, FAQ questions ...): use INTL Text. */
.bz-eyebrow, .bz-badge, .bz-btn, .bz-herosearch__l, .bz-card__t, .bz-quote__n, .bz-loc__c,
.bz-fcol__h, .bz-form__t, .bz-label, .bz-widget__h, .bz-person__n, .bz-logo__t, .bz-navlabel,
.bz-navitem > a, .bz-chip, .bz-hours caption, .bz-faq summary, .bz-menu-toggle,
.bz-logo__word, .bz-fbrand__n, .bz-stat__v {
  --font-heading: var(--font-body);
}
